CONTRAST_CSS = r"""
/* Last in the cascade so every visual identity remains readable in high contrast. */
.school-site.high-contrast, .school-site.high-contrast * {
  background-color: #000 !important;
  background-image: none !important;
  color: #ff0 !important;
  border-color: #ff0 !important;
  box-shadow: none !important;
}
.school-site.high-contrast .nav-link[aria-current='page'] { outline: 2px solid #ff0; }
.school-site.high-contrast img { background-color: transparent !important; }
"""
